select cc.name, p.fiscal_period, min(p.end_date), max(p.end_date), count(*) from analytics.canonical_fact cf join analytics.canonical_concept cc on cc.id=cf.canonical_concept_id join core.period p on p.id=cf.period_id where cf.company_id=2746 and cc.name in ('inventory','cost_of_revenue','cost_of_revenue_resolved','accounts_payable') group by 1,2 order by 1,2;
select cf.company_id, cc.name, max(p.end_date) from analytics.canonical_fact cf join analytics.canonical_concept cc on cc.id=cf.canonical_concept_id join core.period p on p.id=cf.period_id where cf.company_id in (1168,1553,2889,3062,3406,4637) and cc.name in ('total_debt','total_debt_resolved','total_debt_split','employee_count_resolved','cash_and_equivalents') group by 1,2 order by 1,2
